// ── Race condition ──
int counter = 0;
Parallel.For(0, 100000, _ => counter++); // NOT safe
Console.WriteLine(counter); // < 100000!

// ── Fix with Interlocked ──
int safe = 0;
Parallel.For(0, 100000, _ => Interlocked.Increment(ref safe));
Console.WriteLine(safe); // Always 100000 ✓

